const result = $input.first().json;
const text = result.content?.find(item => item.type === 'text')?.text;
const value = result.structuredContent ?? (typeof text === 'string' ? JSON.parse(text) : text);
if (!value || value.error) throw new Error(value?.error || 'Tellseed returned no usable result');
return [{json: {campaignId: value.confirmed.campaignId}}];

const result = $input.first().json;
const text = result.content?.find(item => item.type === 'text')?.text;
const value = result.structuredContent ?? (typeof text === 'string' ? JSON.parse(text) : text);
if (!value || value.error) throw new Error(value?.error || 'Tellseed returned no usable result');
return [{json: {campaignId: value.confirmed.campaignId, approvalUrl: value.approvalUrl, version: value.previewVersion, digest: value.previewDigest, next: 'The workspace owner must open this URL, sign in and approve. Then run the separate Publish approved campaign workflow.'}}];
